import{_ as r,C as n,o as t,c as s,a2 as i,b as d,w as a,a as l,E as c,a3 as u}from"./chunks/framework.Dd_iHz3e.js";const _=JSON.parse('{"title":"14.10 API Design, Rate Limiting & Throttling","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.10-api-design-and-rate-limiting.md","filePath":"system-design/14.10-api-design-and-rate-limiting.md"}'),g={name:"system-design/14.10-api-design-and-rate-limiting.md"};function h(m,e,p,k,f,b){const o=n("Mermaid");return t(),s("div",null,[e[1]||(e[1]=i('<h1 id="_14-10-api-design-rate-limiting-throttling" tabindex="-1">14.10 API Design, Rate Limiting &amp; Throttling <a class="header-anchor" href="#_14-10-api-design-rate-limiting-throttling" aria-label="Permalink to &quot;14.10 API Design, Rate Limiting &amp; Throttling&quot;">​</a></h1><h2 id="_1-plain-english-overview" tabindex="-1">1. Plain English Overview <a class="header-anchor" href="#_1-plain-english-overview" aria-label="Permalink to &quot;1. Plain English Overview&quot;">​</a></h2><p>API design establishes predictable, secure contracts between clients and servers, while rate limiting protects infrastructure from abusive denial-of-service traffic, brute force password attacks, and runaway cloud API billing.</p><hr><h2 id="_2-usage-in-cooking-nexus" tabindex="-1">2. Usage in Cooking Nexus <a class="header-anchor" href="#_2-usage-in-cooking-nexus" aria-label="Permalink to &quot;2. Usage in Cooking Nexus&quot;">​</a></h2><ul><li><strong>RESTful Endpoints</strong>: Predictable resource hierarchies ([routes/authRoutes.js](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/routes/authRoutes.js), [routes/memberRoutes.js](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/routes/memberRoutes.js)).</li><li><strong>Edge AI Rate Limiting</strong>: The Lovable AI Gateway enforces HTTP 429 rate limits, intercepted cleanly by [ai-stream.ts:L29-L32](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/27-kitchen-companion-pro/src/lib/ai-stream.ts#L29-L32).</li></ul><hr><h2 id="_3-rate-limiting-algorithm-flow-token-bucket" tabindex="-1">3. Rate Limiting Algorithm Flow: Token Bucket <a class="header-anchor" href="#_3-rate-limiting-algorithm-flow-token-bucket" aria-label="Permalink to &quot;3. Rate Limiting Algorithm Flow: Token Bucket&quot;">​</a></h2>',8)),(t(),d(u,null,{default:a(()=>[c(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Request%5B%22Incoming%20Client%20Request%22%5D%20--%3E%20Bucket%7B%22Tokens%20Available%20in%20Redis%20Bucket%3F%22%7D%0A%20%20%20%20Bucket%20--%3E%7CTokens%20%3E%200%7C%20Consume%5B%22Decrement%201%20Token%20%26%20Forward%20to%20Express%22%5D%0A%20%20%20%20Bucket%20--%3E%7CTokens%20%3D%3D%200%7C%20Reject%5B%22Return%20HTTP%20429%20Too%20Many%20Requests%22%5D%0A%0A%20%20%20%20RefillLoop%5B%22Background%20Clock%3A%20Refill%2010%20Tokens%20every%20second%22%5D%20--%3E%7CRefill%20up%20to%20Max%20Capacity%7C%20Bucket%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<hr><h2 id="_4-rate-limiting-algorithms-comparison" tabindex="-1">4. Rate Limiting Algorithms Comparison <a class="header-anchor" href="#_4-rate-limiting-algorithms-comparison" aria-label="Permalink to &quot;4. Rate Limiting Algorithms Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Algorithm</th><th>Mechanism</th><th>Memory Footprint</th><th>Burst Handling</th><th>Accuracy</th><th>Fit for Cooking Nexus</th></tr></thead><tbody><tr><td><strong>Token Bucket (Recommended)</strong></td><td>Tokens added at constant rate; consumed per request</td><td>Low (2 keys: count + timestamp)</td><td>Handles short bursts up to capacity</td><td>High</td><td>Optimal for AI Chat &amp; Vision Ingest</td></tr><tr><td><strong>Leaky Bucket</strong></td><td>Requests enter queue and leak at constant rate</td><td>Moderate (Queue buffer)</td><td>Smooths out traffic, zero bursts</td><td>High</td><td>Optimal for video transcoding jobs</td></tr><tr><td><strong>Fixed Window Counter</strong></td><td>Counts requests in fixed time block (e.g. 1 min)</td><td>Ultra-Low (Single integer key)</td><td>Vulnerable to 2x burst at window edges</td><td>Low</td><td>Basic dev testing only</td></tr><tr><td><strong>Sliding Window Log</strong></td><td>Stores timestamp of every request in sorted set</td><td>Heavy (O(N) memory per client)</td><td>Perfect accuracy, no window burst</td><td>Ultra-High</td><td>Prohibitive memory cost at scale</td></tr><tr><td><strong>Sliding Window Counter</strong></td><td>Blends previous and current window counts</td><td>Low (Weighted math)</td><td>Smooths window boundary spikes</td><td>High (~99%)</td><td>Excellent for public API routes</td></tr></tbody></table><hr><h2 id="_5-rate-limit-policies-in-production" tabindex="-1">5. Rate Limit Policies in Production <a class="header-anchor" href="#_5-rate-limit-policies-in-production" aria-label="Permalink to &quot;5. Rate Limit Policies in Production&quot;">​</a></h2><ul><li><strong>Authentication Route (<code>POST /api/auth/login</code>)</strong>: Strict sliding window limit of <strong>5 requests per 15 minutes per IP address</strong> to prevent email spamming.</li><li><strong>Vision Ingestion Route (<code>POST /api/vision</code>)</strong>: Token bucket allowing <strong>2 requests/sec per registered deviceId</strong>, with a burst allowance of 10 tokens.</li><li><strong>AI Streaming Edge (<code>POST /functions/v1/chef-ai</code>)</strong>: <strong>15 requests per minute per authenticated user</strong>, with daily credit quotas.</li></ul><hr><h2 id="_6-what-breaks-first-at-scale" tabindex="-1">6. What Breaks First at Scale? <a class="header-anchor" href="#_6-what-breaks-first-at-scale" aria-label="Permalink to &quot;6. What Breaks First at Scale?&quot;">​</a></h2><ul><li><strong>At 10x</strong>: Shared NAT IP blocking: multiple users on a university or office Wi-Fi network sharing a public IP get rate-limited together if limited strictly by IP.</li><li><strong>At 100x</strong>: Redis rate limiter latency: querying Redis for every incoming optical frame adds 2ms of network overhead if not collocated in the same VPC.</li><li><strong>At 1,000x</strong>: Distributed clock skew across edge nodes causing inconsistent sliding window calculations.</li></ul><hr><h2 id="_7-senior-engineer-improvements" tabindex="-1">7. Senior Engineer Improvements <a class="header-anchor" href="#_7-senior-engineer-improvements" aria-label="Permalink to &quot;7. Senior Engineer Improvements&quot;">​</a></h2><p>Implement <strong>Tiered Composite Rate Limiting</strong>:</p><ol><li>Global Layer 7 WAF (Cloudflare) rate limits abusive IP ranges before reaching the origin.</li><li>Application rate limiter keys off authenticated <code>userId</code> for logged-in cooks and <code>deviceId</code> for kitchen hardware, avoiding the shared NAT IP dilemma.</li></ol><hr><h2 id="_8-spoken-interview-answer-30-seconds" tabindex="-1">8. Spoken Interview Answer (30 Seconds) <a class="header-anchor" href="#_8-spoken-interview-answer-30-seconds" aria-label="Permalink to &quot;8. Spoken Interview Answer (30 Seconds)&quot;">​</a></h2><p>&quot;To protect Cooking Nexus from denial-of-service surges and runaway LLM billing, we implement a Token Bucket rate limiter in Redis. This allows home cooks to execute rapid bursts of conversation while capping sustained traffic to 15 queries per minute. For hardware telemetry, we key rate limits off the authenticated hardware <code>deviceId</code> rather than the public IP, ensuring that multiple smart appliances operating in the same house never throttle each other.&quot;</p>',16))])}const v=r(g,[["render",h]]);export{_ as __pageData,v as default};
